import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const repo = join(root, "fixtures", "repo");
const checker = join(root, "scripts", "check_links.mjs");
mkdirSync(join(repo, "images"), { recursive: true });
const put = (name, text) => writeFileSync(join(repo, name), text);
execFileSync("git", ["init", "--quiet", repo]);
put("source.js", "const first = 1;\nconst second = 2;\n");
put("empty.txt", "");
put("images/safe.svg", '<svg><path id="shape"/></svg>\n');
put("şey (özel).md", "# İçerik\n");
put("target.md", [
  "# Başlangıç `Kod`", "# Tekrar", "# Tekrar", "# Tekrar-1", "# Tekrar",
  "# İleri", "# [Görünen](target.md)", "# `[x](y)`", "# `<etiket>`",
  "# Başlık &amp; içerik", "Setext İkinci", "-------------", '<a id="manuel"></a>',
  "# [Başvuru][gönderim]", "", "[gönderim]: target.md", "",
  '`<a id="code-only">`', "",
].join("\n"));
put("good.md", [
  "# Başlık", "[base](target.md)", "![image](images/safe.svg)",
  "[parentheses](şey%20(özel).md#i\u0307çerik)", "[escaped parentheses](şey%20\\(özel\\).md#i\u0307çerik)",
  "[angle path](<şey (özel).md#i\u0307çerik>)", `[encoded path](${encodeURIComponent("şey (özel).md")}#${encodeURIComponent("i\u0307çerik")})`,
  `[heading](target.md#${encodeURIComponent("başlangıç-kod")})`,
  "[duplicate](target.md#tekrar-1)", "[collision](target.md#tekrar-1-1)", "[duplicate again](target.md#tekrar-2)",
  `[dotted i](target.md#${encodeURIComponent("i\u0307leri")})`,
  "[heading link text](target.md#görünen)", "[literal code link](target.md#xy)", "[literal code tag](target.md#etiket)",
  "[entity](target.md#başlık--içerik)", "[setext](target.md#setext-i̇kinci)", "[explicit anchor](target.md#manuel)",
  "[reference in heading](target.md#başvuru)", "[same document](#başlık)", "[line](source.js#L1)", "[range](source.js#L1-L2)",
  "[ref link][REF]", "[spaced reference] [ref]", "[ref][]", "[ref]", "![image ref][picture]", "[![linked image][picture]](target.md)",
  "[ref]: <target.md#tekrar-1> \"Başlık\"", "[picture]: images/safe.svg", "",
  "[external](https://example.invalid/no-network)", "[angle external](<https://example.invalid/angle>)", "<https://example.invalid/auto>",
  "[email](mailto:test@example.invalid)", "[svg id](images/safe.svg#shape)",
  '[quoted title](target.md "title with ) bracket")',
  "`[ignore](absent-inline.md)`", "``[ignore](absent-multi.md) ` x``", "\\[escaped](absent-escaped.md)",
  "```md", "[ignore](absent-fenced.md)", "```", "~~~", "[ignore](absent-tilde.md)", "~~~~",
  "<!-- [ignore](absent-comment.md) -->", "",
].join("\n"));
execFileSync("git", ["add", "good.md", "target.md", "şey (özel).md", "source.js", "empty.txt", "images/safe.svg"], { cwd: repo });
put("untracked.md", "[ignore untracked](absent-untracked.md)\n");

const results = [];
const invoke = (name, args, expected, code, cwd = repo) => {
  const execution = spawnSync(process.execPath, [checker, "--json", ...args], { cwd, encoding: "utf8" });
  const output = JSON.parse(execution.stdout);
  const result = { name, command: [process.execPath, checker, "--json", ...args], cwd, rc: execution.status, stdout: output, stderr: execution.stderr };
  results.push(result);
  assert.equal(execution.status, expected, JSON.stringify(result));
  if (code) assert.ok(output.errors.some((error) => error.code === code), JSON.stringify(result));
  return output;
};

try {
  const normal = invoke("default_tracked_markdown", [], 0);
  assert.equal(normal.filesChecked, 3);
  assert.equal(normal.externalHttpSkipped, 3);
  assert.equal(normal.otherSchemesSkipped, 1);
  assert.equal(normal.fragmentsSkipped.length, 1);
  assert.ok(normal.linksChecked > 0);
  const explicit = invoke("explicit_and_duplicate_file_arguments", ["good.md", "good.md"], 0);
  assert.equal(explicit.filesChecked, 1);
  put("speckit_labels.md", [
    "- [x] T106 [P] [US4] Dar görev açıklaması.",
    "- [x] T203 [P] [US1] [US2] Paylaşılan görev açıklaması.",
    "- [x] [NEEDS CLARIFICATION] işareti kalmadı.",
    "[P]\n[US7]", "",
  ].join("\n"));
  const speckit = invoke("speckit_labels_are_text", ["speckit_labels.md"], 0);
  assert.equal(speckit.linksChecked, 0);
  assert.deepEqual(speckit.errors, []);
  put("defined_spaced_reference.md", "[görünür] [hedef]\n[satır geçişli]\n[hedef]\n\n[hedef]: target.md#başlangıç-kod\n");
  const spaced = invoke("defined_spaced_and_newline_references", ["defined_spaced_reference.md"], 0);
  assert.equal(spaced.linksChecked, 2);
  const negativeCases = [
    ["missing_path", "[bad](missing.md)\n", "missing_path"],
    ["missing_anchor", "[bad](target.md#missing)\n", "missing_anchor"],
    ["missing_reference", "[bad][missing]\n", "missing_reference"],
    ["adjacent_tag_missing_reference", "[P][US4]\n", "missing_reference"],
    ["spaced_collapsed_reference", "[missing] []\n", "missing_reference"],
    ["defined_spaced_missing_path", "[label] [ref]\n\n[ref]: absent-spaced.md\n", "missing_path"],
    ["defined_spaced_missing_anchor", "[label] [ref]\n\n[ref]: target.md#absent-anchor\n", "missing_anchor"],
    ["missing_image_reference", "![bad][missing]\n", "missing_reference"],
    ["collapsed_reference", "[missing][]\n", "missing_reference"],
    ["malformed_link", "[bad](target.md\n", "malformed_link"],
    ["malformed_reference", "[bad]: <target.md\n", "malformed_reference"],
    ["malformed_encoding", "[bad](target%ZZ.md)\n", "malformed_url"],
    ["line_zero", "[bad](source.js#L0)\n", "invalid_line_range"],
    ["line_overflow", "[bad](source.js#L3)\n", "invalid_line_range"],
    ["line_reversed", "[bad](source.js#L2-L1)\n", "invalid_line_range"],
    ["malformed_line_range", "[bad](source.js#L1-Lx)\n", "invalid_line_range"],
    ["empty_line_target", "[bad](empty.txt#L1)\n", "invalid_line_range"],
    ["repository_escape", "[bad](../outside.md)\n", "missing_path"],
    ["code_anchor_is_not_html", "[bad](target.md#code-only)\n", "missing_anchor"],
    ["line_on_directory", "[bad](images#L1)\n", "unreadable_fragment_target"],
    ["nested_image_missing", "[![bad](missing-image.svg)](target.md)\n", "missing_path"],
  ];
  writeFileSync(join(dirname(repo), "outside.md"), "# Outside\n");
  for (const [name, content, code] of negativeCases) {
    put(`${name}.md`, content);
    const output = invoke(name, [`${name}.md`], 1, code);
    assert.equal(output.errors[0].line, 1);
  }
  put("invalid_utf8.md", Buffer.from([0xff, 0xfe]));
  invoke("invalid_utf8_input", ["invalid_utf8.md"], 2, "invalid_input_file");
  invoke("missing_input_file", ["nonexistent-input.md"], 2, "invalid_input_file");
  invoke("unknown_argument", ["--nonsense"], 2, "invalid_argument");
  invoke("outside_git_repository", [], 2, "repository_unavailable", dirname(repo));
  const plain = spawnSync(process.execPath, [checker, "good.md"], { cwd: repo, encoding: "utf8" });
  assert.equal(plain.status, 0);
  assert.match(plain.stdout, /dış HTTP\(S\) kontrol edilmedi: 3/);
  const syntax = spawnSync(process.execPath, ["--check", checker], { encoding: "utf8" });
  assert.equal(syntax.status, 0, syntax.stderr);
  const summary = { result: "pass", date: new Date().toISOString(), checker, fixtureRepository: repo, commandCases: results.length, plainOutputRc: plain.status, syntaxRc: syntax.status, node: process.version };
  writeFileSync(join(root, "verification-result.json"), JSON.stringify(summary, null, 2) + "\n");
  writeFileSync(join(root, "verification-log.json"), JSON.stringify(results, null, 2) + "\n");
  process.stdout.write(JSON.stringify(summary, null, 2) + "\n");
} catch (error) {
  writeFileSync(join(root, "verification-log.json"), JSON.stringify(results, null, 2) + "\n");
  writeFileSync(join(root, "verification-result.json"), JSON.stringify({ result: "fail", message: error.message, casesRun: results.length }, null, 2) + "\n");
  throw error;
}
